def match(resume, jd):
    resume_words = set(resume.lower().split())
    jd_words = {word for word in jd.lower().split() if len(word) > 3}
    return len(resume_words & jd_words) / len(jd_words)

score = match('python sql rag evals docker', 'python sql rag kubernetes')
print(round(score, 2))

